    p = _period(out)
    for r, row in enumerate(out):
        if not any(v == 0 for v in row):
            continue
        by_residue = {}
        for residue in range(p):
            counts = Counter(row[c] for c in range(residue, w, p) if row[c] != 0)
            if counts:
                # Modal color at this row's horizontal-period phase.
                by_residue[residue] = counts.most_common(1)[0][0]
        for c, value in enumerate(row):
            if value == 0 and c % p in by_residue:
                out[r][c] = by_residue[c % p]
    return out
