def transform(grid):
    out = [list(row) for row in grid]
    if not out or not out[0]:
        return out
    h, w = len(out), len(out[0])
    period = 5  # observed repeating five-color raster in the patterned field
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue
            # Restore the two-color frame surrounding the raster.
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                counts = Counter(
                    grid[r][x] for x in range(3, w)
                    if x % period == c % period and grid[r][x] not in (0, 4)
                )
                if counts:
                    out[r][c] = counts.most_common(1)[0][0]
    return out
